// Per-monitor DPI helpers for the candidate and message windows (upstream #960).
//
// Generated by omp (Qwen3.8-Flash-Next) without human creative authorship.
// SPDX-License-Identifier: LGPL-2.1-or-later
//
// PCMan's proposal for #960: measure the DPI of the monitor the host window
// lives on via GetDpiForWindow, with the old primary-monitor measurement
// (GetDeviceCaps(LOGPIXELSY)) as the fallback. Both font-building call paths
// (the pre-session font in the constructor and the rebuild in
// updateCandidates) share these two functions.

#ifndef PIME_DPI_UTILS_H
#define PIME_DPI_UTILS_H

// GetDpiForWindow is declared from the Windows 10 SDK level on; the ADR 0001
// floor makes that the target of every build that includes this header.
#ifndef _WIN32_WINNT
#define _WIN32_WINNT 0x0A00
#endif
#ifndef NTDDI_VERSION
#define NTDDI_VERSION 0x0A000000
#endif

#include <windows.h>

namespace PIME {

// DPI of the monitor hosting `hwnd`; the system DPI when no window is known.
inline UINT dpiForWindow(HWND hwnd) {
	if (hwnd) {
		const UINT dpi = GetDpiForWindow(hwnd);
		if (dpi != 0) {
			return dpi;
		}
	}
	const HDC hdc = GetDC(NULL);
	if (!hdc) {
		return 96;
	}
	const UINT dpi = GetDeviceCaps(hdc, LOGPIXELSY);
	ReleaseDC(NULL, hdc);
	return dpi != 0 ? dpi : 96;
}

// Negative LOGFONT height for a point size at `dpi`, the same MulDiv
// arithmetic both call paths use.
inline int candFontHeightFor(int fontSize, UINT dpi) {
	return -MulDiv(fontSize, (int)(dpi != 0 ? dpi : 96), 72);
}

} // namespace PIME

#endif // PIME_DPI_UTILS_H
